#include <iostream>
#include <ranges>
#include <vector>

int main()
{
    const std::vector<int> pages{1, 2, 3, 4, 5, 6};
    auto selected = pages
        | std::views::filter([](int value) { return value % 2 == 0; })
        | std::views::transform([](int value) { return value * 10; });
    std::vector<int> saved;
    for (int value : selected) {
        std::cout << value << '\n';
        saved.push_back(value);
    }
    std::cout << "Saved: " << saved.size() << '\n';
}
